try (DataLoader.BatchStream stream = DataLoader.builder(Path.of("dataset.jsld"))
        .featureCount(8)
        .batchSize(128)
        .open()) {
    for (int epoch = 0; epoch < 3; epoch++) {
        while (stream.next()) {
            DataLoader.Batch batch = stream.batch();
            int rows = batch.rows();
        }
        stream.rewind();
    }
}

DataLoader.Builder builder = DataLoader.builder(Path.of("dataset.jsld"))
        .featureCount(8)
        .batchSize(256)
        .shuffle(true)
        .seed(7);
try (DataLoader.MappedBatchStream stream = builder.openMapped()) {
    while (stream.next()) {
        int rows = stream.batch().rows();
    }
}

